// Package subscribers manages a store of newsletter subscribers, backed by
// PostgreSQL with queries generated by sqlc (see the db subpackage).
package subscribers

import (
	"context"
	"fmt"

	pgmig "github.com/infodancer/web/newsletter/migrations/postgres"
	"github.com/infodancer/web/newsletter/subscribers/db"
	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/jackc/pgx/v5/stdlib"
	"github.com/pressly/goose/v3"
)

// migrationsTableName is newsletter's dedicated goose version table, distinct
// from the host's default goose_db_version so migration histories never collide
// when components share a database.
const migrationsTableName = "newsletter_goose_db_version"

// Store records subscribers over a PostgreSQL connection pool.
type Store struct {
	q    *db.Queries
	pool *pgxpool.Pool
}

// New creates a subscriber Store over an existing pool. The caller owns the
// pool (typically the host's shared pool) and should apply the schema first
// with Migrate.
func New(pool *pgxpool.Pool) *Store {
	return &Store{q: db.New(pool), pool: pool}
}

// Pool returns the underlying connection pool.
func (s *Store) Pool() *pgxpool.Pool { return s.pool }

// Migrate applies the embedded PostgreSQL migrations against pool. It is safe to
// call repeatedly; goose tracks applied versions in newsletter_goose_db_version.
func Migrate(ctx context.Context, pool *pgxpool.Pool) error {
	sqldb := stdlib.OpenDBFromPool(pool)
	defer func() { _ = sqldb.Close() }()

	prov, err := goose.NewProvider(goose.DialectPostgres, sqldb, pgmig.FS,
		goose.WithTableName(migrationsTableName),
		goose.WithLogger(goose.NopLogger()),
	)
	if err != nil {
		return fmt.Errorf("newsletter: migrate: %w", err)
	}
	if _, err := prov.Up(ctx); err != nil {
		return fmt.Errorf("newsletter: migrate: %w", err)
	}
	return nil
}

// Insert adds email to the subscribers table.
// Returns true if the address was new, false if already present.
func (s *Store) Insert(email string) (bool, error) {
	n, err := s.q.InsertSubscriber(context.Background(), email)
	if err != nil {
		return false, fmt.Errorf("insert: %w", err)
	}
	return n > 0, nil
}

// MarkSynced records the current UTC time as the sync timestamp for email.
func (s *Store) MarkSynced(email string) error {
	return s.q.MarkSynced(context.Background(), email)
}
